  // Automations
  'automations.view', 'automations.manage', 'automations.view_execution_log', 'automations.system_admin',
])

/** Admin permissions: full operational access minus billing/plan/account management. */
const ADMIN_PERMISSIONS: ReadonlySet<PermissionKey> = new Set<PermissionKey>([
  // Global
  'global.view_own_profile', 'global.change_password', 'global.view_staff_list',
  'global.invite_staff', 'global.deactivate_staff', 'global.change_staff_role',
  'global.manage_property_settings',
  // Reservations
  'reservations.read', 'reservations.create', 'reservations.update',
  'reservations.check_in', 'reservations.check_out', 'reservations.cancel',
  'reservations.refund', 'reservations.extend', 'reservations.modify_dates',
  'reservations.modify_guests', 'reservations.noshow', 'reservations.renew',
  // Financial
  'financial.view_balance', 'financial.view_transactions', 'financial.record_payment',
  'financial.create_charge', 'financial.refund', 'financial.configure_schedule',
  'financial.view_processor_config', 'financial.switch_processor',
  // Guest comms
  'guest_comms.view_delivery_log', 'guest_comms.view_all_logs',
  'guest_comms.edit_templates', 'guest_comms.configure_branding', 'guest_comms.view_opt_out_list',
  // Housekeeping
  'housekeeping.view_all', 'housekeeping.view_assigned', 'housekeeping.create_manual',
  'housekeeping.reassign', 'housekeeping.start_complete', 'housekeeping.approve_site_ready',
  'housekeeping.manage_checklists',
  // Maintenance
  'maintenance.view_all', 'maintenance.view_assigned', 'maintenance.create_wo',
  'maintenance.assign_wo', 'maintenance.update_assigned', 'maintenance.request_onhold',
  'maintenance.approve_onhold', 'maintenance.view_labor_rates', 'maintenance.enter_labor_cost',
  'maintenance.cancel_wo', 'maintenance.manage_vendors', 'maintenance.manage_pm_schedules',
  'maintenance.manage_budgets', 'maintenance.view_cost_reports',
  // Gate access
  'gate_access.view_log', 'gate_access.view_health', 'gate_access.configure_vendor',
  'gate_access.trigger_health_check', 'gate_access.log_incident',
  // Marketing & SEO
  'marketing_seo.view_analytics', 'marketing_seo.edit_listings', 'marketing_seo.manage_photos',
  'marketing_seo.configure_seo', 'marketing_seo.manage_reviews', 'marketing_seo.manage_integrations',
  'marketing_seo.view_campaigns',
  // Activities
  'activities.view', 'activities.schedule', 'activities.book',
  // Documentation
  'docs.view_guest', 'docs.view_staff_sops', 'docs.create_edit',
  'docs.publish_archive', 'docs.view_acknowledgment_log', 'docs.override_acknowledgment',
  // Dynamic pricing
  'dynamic_pricing.view_config', 'dynamic_pricing.update_config', 'dynamic_pricing.enable_disable',
  'dynamic_pricing.view_revenue', 'dynamic_pricing.view_audit_log',
  // Automations
  'automations.view', 'automations.manage', 'automations.view_execution_log',
])

/** Manager permissions: elevated operational access, no pricing/financial config. */
const MANAGER_PERMISSIONS: ReadonlySet<PermissionKey> = new Set<PermissionKey>([
  // Global
  'global.view_own_profile', 'global.change_password', 'global.view_staff_list',
  // Reservations
  'reservations.read', 'reservations.create', 'reservations.update',
  'reservations.check_in', 'reservations.check_out', 'reservations.cancel',
  'reservations.extend', 'reservations.modify_dates', 'reservations.modify_guests',
  'reservations.noshow', 'reservations.renew',
  // Financial
  'financial.view_balance', 'financial.view_transactions', 'financial.record_payment', 'financial.create_charge',
  // Guest comms
  'guest_comms.view_delivery_log', 'guest_comms.view_all_logs',
  // Housekeeping
  'housekeeping.view_all', 'housekeeping.view_assigned', 'housekeeping.create_manual',
  'housekeeping.reassign', 'housekeeping.start_complete',
  // Maintenance
  'maintenance.view_all', 'maintenance.view_assigned', 'maintenance.create_wo',
  'maintenance.assign_wo', 'maintenance.update_assigned', 'maintenance.request_onhold',
  'maintenance.approve_onhold', 'maintenance.view_labor_rates', 'maintenance.enter_labor_cost',
  // Gate access
  'gate_access.view_log', 'gate_access.view_health', 'gate_access.log_incident',
  // Marketing & SEO
  'marketing_seo.view_analytics', 'marketing_seo.edit_listings', 'marketing_seo.manage_photos',
  'marketing_seo.manage_reviews', 'marketing_seo.view_campaigns',
  // Activities
  'activities.view', 'activities.schedule', 'activities.book',
  // Documentation
  'docs.view_guest', 'docs.view_staff_sops', 'docs.override_acknowledgment',
  // Dynamic pricing
  'dynamic_pricing.view_config', 'dynamic_pricing.view_revenue',
  // Automations
  'automations.view', 'automations.view_execution_log',
])

/**
 * Staff base permissions.
 *
 * By design, staff have NO operational permissions by default.
 * All access is granted through staff categories (front_desk, housekeeping, etc.).
 * This set intentionally only contains global profile permissions.
 */
const STAFF_PERMISSIONS: ReadonlySet<PermissionKey> = new Set<PermissionKey>([
  'global.view_own_profile',
  'global.change_password',
  'docs.view_guest',
])

// ─── Permission look-up ────────────────────────────────────────────────────────

const ROLE_PERMISSIONS: Readonly<Record<EffectiveRole, ReadonlySet<PermissionKey>>> = {
  owner: OWNER_PERMISSIONS,
  admin: ADMIN_PERMISSIONS,
  manager: MANAGER_PERMISSIONS,
  staff: STAFF_PERMISSIONS,
}

/** Get the full permission set for a given role. */
export function getPermissionsForRole(role: EffectiveRole): ReadonlySet<PermissionKey> {
  return ROLE_PERMISSIONS[role] ?? STAFF_PERMISSIONS
}

/** Check whether a role has a specific permission. */
export function hasPermission(role: EffectiveRole, key: PermissionKey): boolean {
  return getPermissionsForRole(role).has(key)
}

/** Check whether a role has any of the given permissions. */
export function hasAnyPermission(role: EffectiveRole, keys: readonly PermissionKey[]): boolean {
  const perms = getPermissionsForRole(role)
  return keys.some((k) => perms.has(k))
}

/** Check whether a role has all of the given permissions. */
export function hasAllPermissions(role: EffectiveRole, keys: readonly PermissionKey[]): boolean {
  const perms = getPermissionsForRole(role)
  return keys.every((k) => perms.has(k))
}

/**
 * Check if a role meets a minimum authority level AND has the specific permission.
 * Useful for operations that require both a minimum role AND a permission.
 */
export function roleCanPerform(role: EffectiveRole, minimumRole: EffectiveRole, key: PermissionKey): boolean {
  return roleMeetsMinimum(role, minimumRole) && hasPermission(role, key)
}

/**
 * Route guard helpers for Camp-OS RBAC.
 *
 * These functions are designed for use in Next.js API route handlers.
 * They return `NextResponse` on denial (so the caller can `return` it directly)
 * or a `ResolvedAccess` object on success.
 */

import { NextResponse } from 'next/server'
import type { SupabaseClient } from '@supabase/supabase-js'
import type { EffectiveRole } from './roles'
import type { PermissionKey } from './permissions'
import type { StaffCategory } from './staff-categories'
import {
  resolveUserPropertyAccess,
  type ResolvedAccess,
} from './resolve-access'
import { hasPermission } from './permissions'
import { staffHasPermission } from './staff-categories'

// ─── Requirements interface ────────────────────────────────────────────────────

export interface AccessRequirements {
  propertyId: string
  /** Minimum effective role required. Checked before permission. */
  minimumRole?: EffectiveRole
  /** Specific permission key required. */
  permission?: PermissionKey
  /** Require at least one of these categories (staff role only). */
  anyCategory?: StaffCategory[]
  /** Any of these roles — alternative to minimumRole for multi-role paths. */
  anyOfRoles?: EffectiveRole[]
}

// ─── Guard result type ─────────────────────────────────────────────────────────

type GuardResult =
  | { access: ResolvedAccess; denied: false }
  | { denied: true; response: NextResponse }

function deny(status: number, message: string): GuardResult {
  return {
    denied: true,
    response: NextResponse.json(
      { success: false, error: { code: `AUTH_${status === 404 ? '004' : '003'}`, message } },
      { status },
    ),
  }
}

// ─── Main guard function ───────────────────────────────────────────────────────

/**
 * Check property access and optional permission/category requirements.
 *
 * Usage in route handlers:
 * ```ts
 * const result = await checkPropertyAccess(supabase, userId, {
 *   propertyId,
 *   minimumRole: 'admin',
 *   permission: 'financial.refund',
 * })
 * if (result.denied) return result.response
 * const { access } = result
 * ```
 */
export async function checkPropertyAccess(
  supabase: SupabaseClient,
  userId: string,
  requirements: AccessRequirements,
): Promise<GuardResult> {
  const { propertyId, minimumRole, permission, anyCategory, anyOfRoles } = requirements

  // Resolve base access
  const access = await resolveUserPropertyAccess(supabase, propertyId, userId)
  if (!access) {
    return deny(404, 'Property not found or access denied')
  }

  // Platform admin bypasses everything
  if (access.isPlatformAdmin) {
    return { access, denied: false }
  }

  const role = access.role

  // If no specific role required, just having access is enough
  if (!minimumRole && !anyOfRoles && !permission) {
    return { access, denied: false }
  }

  // Check minimum role
  if (minimumRole && role) {
    const ROLE_RANK: Record<EffectiveRole, number> = {
      owner: 40, admin: 30, manager: 20, staff: 10,
    }
    if ((ROLE_RANK[role] ?? 0) < (ROLE_RANK[minimumRole] ?? 0)) {
      return deny(403, 'Insufficient role for this operation')
    }
  }

  // Check anyOfRoles (alternative role check)
  if (anyOfRoles && role && !anyOfRoles.includes(role)) {
    return deny(403, 'Insufficient role for this operation')
  }

  // Check permission
  if (permission && role) {
    // First check the role's built-in permissions (for manager+)
    if (hasPermission(role, permission)) {
      return { access, denied: false }
    }

    // For staff role, check if any category grants this permission
    if (role === 'staff') {
      if (staffHasPermission(access.categories, permission)) {
        return { access, denied: false }
      }
    }

    return deny(403, 'Permission denied for this operation')
  }

  // Check category requirement
  if (anyCategory && anyCategory.length > 0 && role === 'staff') {
    const hasMatch = access.categories.includes('all') ||
      anyCategory.some((cat) => access.categories.includes(cat))
    if (!hasMatch) {
      return deny(403, 'Category access required for this operation')
    }
  }

  return { access, denied: false }
}

// ─── Convenience wrappers ──────────────────────────────────────────────────────

/**
 * Verify the user can access a property (any role, owner OR active staff).
 * Returns access on success or a 404 NextResponse on denial.
 */
export async function requirePropertyMembership(
  supabase: SupabaseClient,
  userId: string,
  propertyId: string,
): Promise<ResolvedAccess | NextResponse> {
  const result = await checkPropertyAccess(supabase, userId, { propertyId })
  if (result.denied) return result.response
  return result.access
}

/**
 * Verify the user meets role/permission/category requirements for an operation.
 */
export async function requirePropertyAccess(
  supabase: SupabaseClient,
  userId: string,
  requirements: AccessRequirements,
): Promise<ResolvedAccess | NextResponse> {
  const result = await checkPropertyAccess(supabase, userId, requirements)
  if (result.denied) return result.response
  return result.access
}

/**
 * Type guard to check if the result of requirePropertyAccess / requirePropertyMembership
 * is a NextResponse (denied) or ResolvedAccess (granted).
 */
export function isDenied(result: ResolvedAccess | NextResponse): result is NextResponse {
  return result instanceof NextResponse
}

/**
 * Core access resolver for Camp-OS RBAC.
 *
 * Resolves the current user's role, company, and staff categories for a property
 * in a single pass. Follows the proven `verifyPropertyAccess()` pattern from
 * staff-management-queries.ts.
 */

import type { SupabaseClient } from '@supabase/supabase-js'
import type { EffectiveRole } from './roles'
import { toEffectiveRole, isDbRole } from './roles'
import type { StaffCategory } from './staff-categories'
import { normaliseCategories } from './staff-categories'

// ─── Resolved access type ──────────────────────────────────────────────────────

export interface ResolvedAccess {
  userId: string
  propertyId: string
  companyId: string | null
  /** Normalised role for application logic (property_admin → admin). */
  role: EffectiveRole | null
  /** Original raw role from the database. */
  rawRole: string | null
  /** Staff categories assigned to the user. Empty if none or non-staff. */
  categories: StaffCategory[]
  /** True when user is the company owner (companies.owner_id === userId). */
  isOwner: boolean
  /** True for owner, admin, or manager roles. */
  isElevated: boolean
  /** True when user has a platform_admin flag in user_metadata. */
  isPlatformAdmin: boolean
}

// ─── Category name resolution ──────────────────────────────────────────────────

/**
 * Resolve category names from `property_role_categories` UUIDs.
 *
 * The `property_staff.role_category_id` column stores an array of UUIDs
 * referencing `property_role_categories.id`. This function fetches the
 * corresponding category names and normalises them.
 */
async function resolveCategoryNames(
  supabase: SupabaseClient,
  categoryIds: string[] | null | undefined,
  propertyId: string,
): Promise<StaffCategory[]> {
  if (!categoryIds || categoryIds.length === 0) return []

  const { data } = await supabase
    .from('property_role_categories')
    .select('name')
    .eq('property_id', propertyId)
    .in('id', categoryIds)

  if (!data || data.length === 0) return []

  return normaliseCategories(data.map((row) => row.name))
}

// ─── Resolver ──────────────────────────────────────────────────────────────────

/**
 * Resolve a user's access to a property.
 *
 * Returns `null` when the user has no access to the property.
 * Throws no errors — callers should treat `null` as "not found / 404".
 */
export async function resolveUserPropertyAccess(
  supabase: SupabaseClient,
  propertyId: string,
  userId: string,
): Promise<ResolvedAccess | null> {
  // 1. Get property → company
  const { data: property } = await supabase
    .from('properties')
    .select('company_id, owner_id')
    .eq('id', propertyId)
    .maybeSingle()

  if (!property) return null

  // 2. Check if user is the company owner
  const companyId: string | null = property.company_id
  const isOwner = property.owner_id === userId

  if (isOwner) {
    return {
      userId,
      propertyId,
      companyId,
      role: 'owner',
      rawRole: 'owner',
      categories: [],
      isOwner: true,
      isElevated: true,
      isPlatformAdmin: false,
    }
  }

  // 3. Check company ownership via companies table
  if (companyId) {
    const { data: company } = await supabase
      .from('companies')
      .select('owner_id')
      .eq('id', companyId)
      .maybeSingle()

    if (company?.owner_id === userId) {
      return {
        userId,
        propertyId,
        companyId,
        role: 'owner',
        rawRole: 'owner',
        categories: [],
        isOwner: true,
        isElevated: true,
        isPlatformAdmin: false,
      }
