    }

    const { data: siteRow, error: siteLookupError } = await supabase
      .from('sites')
      .select('id, status, site_number')
      .eq('id', existingReservation.siteId)
      .eq('property_id', existingReservation.propertyId)
      .is('deleted_at', null)
      .maybeSingle()

    if (siteLookupError || !siteRow) {
      return error(
        ErrorCodes.RESOURCE_NOT_FOUND.code,
        'Site not found for this reservation',
        ErrorCodes.RESOURCE_NOT_FOUND.status
      )
    }

    if (siteRow.status === 'housekeeping') {
      return error(
        ErrorCodes.RESOURCE_004.code,
        'Cannot check in while the site is in housekeeping. Complete housekeeping first.',
        ErrorCodes.RESOURCE_004.status,
        undefined,
        { code: 'SITE_HOUSEKEEPING' }
      )
    }

    const { data: activeSiteStay, error: activeSiteStayError } = await supabase
      .from('reservations')
      .select('id, confirmation_number, check_out_date')
      .eq('property_id', existingReservation.propertyId)
      .eq('site_id', existingReservation.siteId)
      .eq('status', 'checked_in')
      .neq('id', reservationId)
      .limit(1)
      .maybeSingle()

    if (activeSiteStayError) {
      return NextResponse.json(
        error(ErrorCodes.INTERNAL_ERROR, 'Failed to validate site occupancy'),
        { status: 500 }
      )
    }

    if (activeSiteStay) {
      return error(
        ErrorCodes.RESOURCE_004.code,
        'A guest is currently checked in to this site. Please check them out before checking in this reservation.',
        409,
        request,
        { code: 'SITE_OCCUPIED' }
      )
    }

    // Parse and validate request body
    const body = await request.json()

    let validatedRequest: CheckInRequest
    try {
      validatedRequest = CheckInRequestSchema.parse(body)
    } catch (validationError: any) {
      return NextResponse.json(
        error(ErrorCodes.VALIDATION_ERROR, 'Invalid request body', {
          errors: validationError.errors,
        }),
        { status: 400 }
      )
    }

    // Execute command using application layer
    const commandHandler = new CheckInGuestCommandHandler(repository)

    const reservation = await commandHandler.execute({
      reservationId,
      staffUserId: user.id, // Current authenticated user is performing check-in
      balancePaidCents: validatedRequest.balancePaidCents,
      notes: validatedRequest.notes ?? null,
    })

    if (reservation.siteId) {
      const { error: siteUpdateError } = await supabase
        .from('sites')
        .update({
          status: 'occupied',
          updated_at: new Date().toISOString(),
        })
        .eq('id', reservation.siteId)
        .eq('property_id', reservation.propertyId)

      if (siteUpdateError) {
        console.error('[Reservations API v1] Site occupied status update error:', siteUpdateError)
        return error(
          ErrorCodes.INTERNAL_ERROR.code,
          'Guest was checked in but failed to update site status',
          ErrorCodes.INTERNAL_ERROR.status
        )
      }

      if (access.companyId) {
        const supabaseServiceRole = createServiceRoleClient()
        await recordActivityLog(supabaseServiceRole, {
          companyId: access.companyId,
          propertyId: reservation.propertyId,
          action: 'update',
          resource: 'site',
          userId: null,
          details: `Site (number: ${siteRow.site_number}) marked as occupied`,
        })
      }
    }

    if (access.companyId) {
      const supabaseServiceRole = createServiceRoleClient()
      const confirmationNumber = reservation.confirmationNumber.value
      await recordActivityLog(supabaseServiceRole, {
        companyId: access.companyId,
        propertyId: reservation.propertyId,
        action: 'checked_in',
        resource: 'reservation',
        userId: user.id,
        details: `Checked in guest (confirmation ${confirmationNumber})`,
      })
    }

    // Convert to DTO
    const reservationDTO = toReservationDTO(reservation)

    return success(reservationDTO)
  } catch (err: any) {
    console.error('[Reservations API v1] Check-in error:', err)

    // Handle domain validation errors
    if (err.message.includes('confirmed') || err.message.includes('check-in date')) {
      return error('VALIDATION_ERROR', err.message, 400)
    }

    return NextResponse.json(
      error(ErrorCodes.INTERNAL_ERROR, 'Failed to check in guest', {
        message: err.message,
      }),
      { status: 500 }
    )
  }
}

/**
 * StaffRole Value Object
 *
 * Represents the role of a staff member at a property.
 * Roles determine default permission sets.
 */

import { ValueObject } from '@/shared/domain/ValueObject'

export type StaffRoleType = 'owner' | 'admin' | 'manager' | 'staff'

interface StaffRoleProps {
  value: StaffRoleType
}

export class StaffRole extends ValueObject<StaffRoleProps> {
  public static readonly OWNER = new StaffRole({ value: 'owner' })
  public static readonly ADMIN = new StaffRole({ value: 'admin' })
  public static readonly MANAGER = new StaffRole({ value: 'manager' })
  public static readonly STAFF = new StaffRole({ value: 'staff' })

  /**
   * Get the role value
   */
  get value(): StaffRoleType {
    return this.props.value
  }

  /**
   * Factory method to create from string value
   *
   * @param role - Role string
   * @returns StaffRole instance
   * @throws Error if invalid role
   */
  public static fromString(role: string | null): StaffRole {
    if (!role) {
      return StaffRole.STAFF
    }

    const normalized = role.toLowerCase()

    switch (normalized) {
      case 'owner':
        return StaffRole.OWNER
      case 'admin':
      case 'property_admin':
        return StaffRole.ADMIN
      case 'manager':
        return StaffRole.MANAGER
      case 'staff':
        return StaffRole.STAFF
      case 'viewer':
        // Backward compatibility: viewer → staff
        console.warn('[StaffRole] "viewer" role is deprecated, mapping to "staff"')
        return StaffRole.STAFF
      default:
        throw new Error(`Invalid staff role: ${role}`)
    }
  }

  /**
   * Check if this role has higher authority than another
   */
  public hasHigherAuthorityThan(other: StaffRole): boolean {
    const order: StaffRoleType[] = ['staff', 'manager', 'admin', 'owner']
    return order.indexOf(this.props.value) > order.indexOf(other.props.value)
  }

  /**
   * Check if this is an admin role (owner or admin)
   */
  get isAdmin(): boolean {
    return this.props.value === 'owner' || this.props.value === 'admin'
  }

  /**
   * Check if this is the owner role
   */
  get isOwner(): boolean {
    return this.props.value === 'owner'
  }

  /**
   * Check if this role can manage staff (admin or above)
   */
  get canManageStaff(): boolean {
    return this.props.value === 'owner' || this.props.value === 'admin'
  }

  /**
   * Check if this role can manage financial data (admin or above)
   */
  get canManageFinancials(): boolean {
    return this.props.value === 'owner' || this.props.value === 'admin'
  }

  /**
   * Check if this is an elevated role (manager or above)
   */
  get isElevated(): boolean {
    return this.props.value !== 'staff'
  }

  /**
   * Get display name for the role
   */
  get displayName(): string {
    const names: Record<StaffRoleType, string> = {
      owner: 'Owner',
      admin: 'Admin',
      manager: 'Manager',
      staff: 'Staff',
    }
    return names[this.props.value]
  }

  public override toString(): string {
    return this.props.value
  }
}

import type { SupabaseClient, User } from '@supabase/supabase-js'
import { resolveUserPropertyAccess } from '@/lib/rbac/resolve-access'
import { canAccessOperationsModules, canAccessPropertySettings, canManageStaffRoster, canViewFinancials } from '@/lib/rbac/dashboard-guards'

export type DashboardNavVisibility = {
  /** Operations modules (reservations, sites, guests, auditing, analytics) */
  operationsModulesNavVisible: boolean
  /** Staff management page */
  staffManagementNavVisible: boolean
  /** Property settings page */
  propertySettingsNavVisible: boolean
  /** Financial pages (transactions, refunds, deposits) — NEW */
  financialNavVisible: boolean
}

export async function resolveDashboardNavVisibility(
  supabase: SupabaseClient,
  propertyId: string,
  userId: string,
): Promise<DashboardNavVisibility> {
  const access = await resolveUserPropertyAccess(supabase, propertyId, userId)

  if (!access) {
    // Fallback: allow all (shouldn't happen if auth is working)
    return {
      operationsModulesNavVisible: true,
      staffManagementNavVisible: true,
      propertySettingsNavVisible: true,
      financialNavVisible: true,
    }
  }

  return {
    operationsModulesNavVisible: canAccessOperationsModules(access),
    staffManagementNavVisible: canManageStaffRoster(access),
    propertySettingsNavVisible: canAccessPropertySettings(access),
    financialNavVisible: canViewFinancials(access),
  }
}

export type DashboardUserLabels = {
  displayName: string
  roleLabel: string
}

export async function resolveDashboardUserLabels(
  supabase: SupabaseClient,
  user: User,
): Promise<DashboardUserLabels> {
  const metadata = (user.user_metadata ?? {}) as Record<string, unknown>
  const firstName = typeof metadata.first_name === 'string' ? metadata.first_name.trim() : ''
  const lastName = typeof metadata.last_name === 'string' ? metadata.last_name.trim() : ''
  const fullName = [firstName, lastName].filter(Boolean).join(' ')
  const fallbackName =
    typeof metadata.full_name === 'string'
      ? metadata.full_name
      : typeof metadata.name === 'string'
        ? metadata.name
        : ''
  const displayName = fullName || fallbackName || user.email || 'User'

  const { data: ownerCompany } = await supabase
    .from('companies')
    .select('id')
    .eq('owner_id', user.id)
    .limit(1)
    .maybeSingle()

  const userType = typeof metadata.user_type === 'string' ? metadata.user_type : ''
  const roleLabel =
    ownerCompany?.id
      ? 'Owner'
      : userType.length > 0
        ? `${userType.charAt(0).toUpperCase()}${userType.slice(1)}`
        : 'Owner'

  return { displayName, roleLabel }
}

